import { Box, Container, AppBar, Toolbar, IconButton, Badge, Avatar, Typography } from "@mui/material";
import { Outlet, useLocation } from "react-router-dom";
import NotificationsIcon from "@mui/icons-material/Notifications";
import SearchIcon from "@mui/icons-material/Search";
import SettingsIcon from "@mui/icons-material/Settings";
import DashboardSidebar from "../components/layout/DashboardSidebar";

const pageTitles: Record<string, { title: string; subtitle: string }> = {
  "/forecast": {
    title: "Forecast Intelligence",
    subtitle: "Real-time coal stockpile predictions and weather analysis",
  },
  "/model-performance": {
    title: "Model Performance",
    subtitle: "Accuracy metrics and validation analytics",
  },
  "/inference": {
    title: "System Health",
    subtitle: "Pipeline monitoring and system diagnostics",
  },
  "/inference-monitoring": {
    title: "Activity Monitor",
    subtitle: "Live inference tracking and performance metrics",
  },
};

const DashboardLayout = () => {
  const location = useLocation();
  const page = pageTitles[location.pathname] ?? {
    title: "Dashboard",
    subtitle: "Eskom Forecast Management",
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#F8F9FA" }}>
      {/* LEFT SIDEBAR */}
      <DashboardSidebar />

      {/* MAIN CONTENT AREA */}
      <Box sx={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>
        {/* TOP BAR */}
        <AppBar
          position="sticky"
          elevation={0}
          sx={{
            bgcolor: "#FFFFFF",
            borderBottom: "1px solid #E0E0E0",
            color: "#1A1A1A",
          }}
        >
          <Toolbar sx={{ gap: 2, justifyContent: "space-between" }}>
            {/* Page Title */}
            <Box>
              <Typography variant="h6" fontWeight={700} color="#003DA5">
                {page.title}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                {page.subtitle}
              </Typography>
            </Box>

            {/* Right Actions */}
            <Box sx={{ display: "flex", gap: 1, alignItems: "center" }}>
              <IconButton size="small">
                <SearchIcon />
              </IconButton>
              <IconButton size="small">
                <Badge badgeContent={3} color="error">
                  <NotificationsIcon />
                </Badge>
              </IconButton>
              <IconButton size="small">
                <SettingsIcon />
              </IconButton>
              <Avatar
                sx={{
                  bgcolor: "#003DA5",
                  width: 36,
                  height: 36,
                  fontSize: "0.875rem",
                  fontWeight: 700,
                }}
              >
                AD
              </Avatar>
            </Box>
          </Toolbar>
        </AppBar>

        {/* PAGE CONTENT */}
        <Box
          component="main"
          sx={{
            flex: 1,
            overflow: "auto",
            p: 3,
          }}
        >
          <Container
            maxWidth={false}
            disableGutters
            sx={{
              maxWidth: "1600px",
            }}
          >
            <Outlet />
          </Container>
        </Box>
      </Box>
    </Box>
  );
};

export default DashboardLayout;
